// Package outbox writes messages to Postgres in the transaction of the change they describe, forwards them to Kafka
// in commit order and purges the forwarded ones.
//
// An Outbox named "notes" needs these tables, created by the service's migrations:
//
//	CREATE TABLE watermill_notes_outbox (
//	    "offset" bigint GENERATED BY DEFAULT AS IDENTITY,
//	    uuid text NOT NULL,
//	    created_at timestamptz NOT NULL DEFAULT now(),
//	    payload json,
//	    metadata json,
//	    transaction_id xid8 NOT NULL,
//	    PRIMARY KEY (transaction_id, "offset")
//	);
//
//	CREATE TABLE watermill_offsets_notes_outbox (
//	    consumer_group text PRIMARY KEY,
//	    offset_acked bigint,
//	    last_processed_transaction_id xid8 NOT NULL
//	);
package outbox

import (
	"context"
	"regexp"
	"time"

	"github.com/ThreeDotsLabs/watermill"
	"github.com/ThreeDotsLabs/watermill-sql/v4/pkg/sql"
	"github.com/ThreeDotsLabs/watermill/components/forwarder"
	"github.com/ThreeDotsLabs/watermill/message"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

// PartitionKeyHeader is the metadata key whose value the Forwarder uses as the Kafka message key.
const PartitionKeyHeader = "ce_partitionkey"

var validName = regexp.MustCompile(`^[a-z][a-z0-9_]*$`)

type Outbox struct {
	name string
}

func New(name string) (Outbox, error) {
	if !validName.MatchString(name) {
		return Outbox{}, ErrInvalidName.WithAttribute("name", name)
	}

	return Outbox{name: name}, nil
}

func MustNew(name string) Outbox {
	o, err := New(name)
	if err != nil {
		panic(err)
	}

	return o
}

// Publish writes the messages to the outbox in tx, so they reach their topic only if tx commits.
func (o Outbox) Publish(ctx context.Context, tx pgx.Tx, topic string, messages ...*message.Message) (err error) {
	publisher, err := sql.NewPublisher(
		sql.TxFromPgx(tx),
		sql.PublisherConfig{SchemaAdapter: sql.DefaultPostgreSQLSchema{}},
		watermill.NopLogger{},
	)
	if err != nil {
		return ErrPublish.WithCause(err)
	}

	outbox := forwarder.NewPublisher(publisher, forwarder.PublisherConfig{ForwarderTopic: o.forwarderTopic()})

	for _, msg := range messages {
		end := onCreateStart(ctx, msg, topic)

		err := outbox.Publish(topic, msg)
		end(err)

		if err != nil {
			return ErrPublish.WithCause(err)
		}
	}

	return nil
}

// newSubscriber relies on watermill-sql locking the group's offset row in each transaction, so only one replica
// consumes and commit order holds.
func (o Outbox) newSubscriber(pool *pgxpool.Pool) (message.Subscriber, error) {
	// watermill-sql redelivers a message whose ack deadline passes while its handler may still be publishing it.
	noAckDeadline := time.Duration(0)

	return sql.NewSubscriber(
		sql.BeginnerFromPgx(pool),
		sql.SubscriberConfig{
			ConsumerGroup:    o.consumerGroup(),
			AckDeadline:      &noAckDeadline,
			SchemaAdapter:    sql.DefaultPostgreSQLSchema{SubscribeBatchSize: 1},
			OffsetsAdapter:   sql.DefaultPostgreSQLOffsetsAdapter{},
			InitializeSchema: false,
		},
		watermill.NopLogger{},
	)
}

func (o Outbox) forwarderTopic() string {
	return o.name + "_outbox"
}

func (o Outbox) consumerGroup() string {
	return o.name + "-forwarder"
}

func (o Outbox) messagesTable() string {
	return pgx.Identifier{"watermill_" + o.forwarderTopic()}.Sanitize()
}

func (o Outbox) offsetsTable() string {
	return pgx.Identifier{"watermill_offsets_" + o.forwarderTopic()}.Sanitize()
}
